import java.util.*;

public class Main {
    public static void main(String[] args) {
        BloomFilter seenUrls = new BloomFilter(10000, 5); // small demo filter, still plenty of bits for a handful of URLs

        seenUrls.add("https://example.com/page1");
        seenUrls.add("https://example.com/page2");
        seenUrls.add("https://test.com/home");

        System.out.println("Seen page1 correctly detected: " + seenUrls.mightContain("https://example.com/page1"));
        System.out.println("Seen page2 correctly detected: " + seenUrls.mightContain("https://example.com/page2"));
        System.out.println("Seen test.com home correctly detected: " + seenUrls.mightContain("https://test.com/home"));
        System.out.println("Never-added URL correctly reported as new: " + !seenUrls.mightContain("https://never-added.com/page"));

        PolitenessManager politeness = new PolitenessManager(1000); // require at least 1000 ms between fetches to the same domain

        System.out.println("First fetch to example.com at time 0 allowed: " + politeness.canFetchNow("example.com", 0));
        politeness.recordFetch("example.com", 0);

        System.out.println("Second fetch to example.com at time 500 (too soon) allowed: " + politeness.canFetchNow("example.com", 500));
        System.out.println("Meanwhile, a different domain, test.com, at time 500 allowed: " + politeness.canFetchNow("test.com", 500));

        System.out.println("Fetch to example.com at time 1200 (enough time passed) allowed: " + politeness.canFetchNow("example.com", 1200));
    }
