// A fixed-size, space-efficient structure for probabilistic set membership.
// Guarantees no false negatives; may rarely report a false positive.
class BloomFilter {
    private final BitSet bits;                  // the shared bit array
    private final int size;                        // total number of bits
    private final int[] seeds;                        // one hash seed per hash function

    public BloomFilter(int sizeInBits, int numHashes) {
        this.size = sizeInBits;                              // store the bit array size
        this.bits = new BitSet(sizeInBits);                     // allocate the bit array, all clear
        this.seeds = new int[numHashes];                           // one seed per hash function
        Random random = new Random(42L);                              // fixed seed, so results are reproducible every run
        for (int i = 0; i < numHashes; i++) seeds[i] = random.nextInt(); // one independent seed per hash function
    }

    // Marks a URL as seen by setting one bit per hash function.
    public void add(String url) {
        for (int seed : seeds) {
            bits.set(indexFor(url, seed)); // set this hash function's bit
        }
    }

    // Returns false only if the URL is definitely new; true means probably
    // already seen, with a small, bounded chance of being a false positive.
    public boolean mightContain(String url) {
        for (int seed : seeds) {
            if (!bits.get(indexFor(url, seed))) {
                return false; // this bit was never set, so this URL is definitely new
            }
        }
        return true; // every bit was already set, probably already seen
    }

    private int indexFor(String url, int seed) {
        int hashCode = url.hashCode() ^ seed; // combine the URL's hash with this function's own seed
        return Math.floorMod(hashCode, size);    // map into a valid bit index
    }
}

// Enforces a minimum delay between fetches to the same domain, tracked
// independently per domain.
class PolitenessManager {
    private final Map<String, Long> lastFetchAtByDomain = new HashMap<>(); // domain -> last fetch timestamp
    private final long minDelayMillis;                                       // minimum gap required between fetches

    public PolitenessManager(long minDelayMillis) {
        this.minDelayMillis = minDelayMillis; // store the configured minimum delay
    }

    // Returns true if enough time has passed since this domain was last fetched.
    public boolean canFetchNow(String domain, long currentTimeMillis) {
        Long lastFetchAt = lastFetchAtByDomain.get(domain); // when this domain was last fetched, if ever
        if (lastFetchAt == null) return true;                  // never fetched before, always allowed
        return (currentTimeMillis-lastFetchAt) >= minDelayMillis; // enough time must have passed
    }

    // Records that a fetch to this domain just happened, at the given time.
    public void recordFetch(String domain, long currentTimeMillis) {
        lastFetchAtByDomain.put(domain, currentTimeMillis); // remember this fetch's timestamp
    }
}

