// A 32-bit polynomial string hash (same recurrence used by Java's own
// String.hashCode): deterministic across languages given the same input.
int32_t stringHash(const std::string& s) {
    int32_t h = 0;
    for (unsigned char c : s) h = 31 * h + static_cast<int32_t>(c);
    return h;
}

// A small, fixed linear-congruential generator purely so the demo's hash
// seeds are reproducible byte-for-byte from one run to the next.
class SeededRandom {
public:
    explicit SeededRandom(uint64_t seed) : state_((seed ^ 0x5DEECE66DULL) & ((1ULL << 48) - 1)) {}
    int32_t nextInt() {
        state_ = (state_ * 0x5DEECE66DULL + 0xBULL) & ((1ULL << 48) - 1);
        return static_cast<int32_t>(state_ >> 16);
    }

private:
    uint64_t state_;
};

// A fixed-size, space-efficient structure for probabilistic set membership.
// Guarantees no false negatives; may rarely report a false positive.
class BloomFilter {
public:
    BloomFilter(int sizeInBits, int numHashes) : size_(sizeInBits), bits_((sizeInBits + 63) / 64, 0) {
        SeededRandom rng(42);   // fixed seed, so results are reproducible every run
        for (int i = 0; i < numHashes; i++) seeds_.push_back(rng.nextInt());   // one hash seed per hash function
    }

    // Marks a URL as seen by setting one bit per hash function.
    void add(const std::string& url) {
        for (int seed : seeds_) setBit(indexFor(url, seed));   // set this hash function's bit
    }

    // Returns false only if the URL is definitely new; true means probably
    // already seen, with a small, bounded chance of being a false positive.
    bool mightContain(const std::string& url) {
        for (int seed : seeds_) {
            if (!getBit(indexFor(url, seed))) return false;   // this bit was never set, so this URL is definitely new
        }
        return true;   // every bit was already set, probably already seen
    }

private:
    int indexFor(const std::string& url, int seed) {
        int32_t hashCode = stringHash(url) ^ seed;   // combine the URL's hash with this function's own seed
        int32_t m = hashCode % size_;
        if (m < 0) m += size_;                          // floor-mod: keep the result non-negative
        return m;                                          // map into a valid bit index
    }
    void setBit(int index) { bits_[index / 64] |= (1ULL << (index % 64)); }
    bool getBit(int index) { return (bits_[index / 64] & (1ULL << (index % 64))) != 0; }

    int size_;                       // total number of bits
    std::vector<uint64_t> bits_;        // the shared bit array
    std::vector<int> seeds_;               // one hash seed per hash function
};

// Enforces a minimum delay between fetches to the same domain, tracked
// independently per domain.
class PolitenessManager {
public:
    explicit PolitenessManager(long minDelayMillis) : minDelayMillis_(minDelayMillis) {}

    // Returns true if enough time has passed since this domain was last fetched.
    bool canFetchNow(const std::string& domain, long currentTimeMillis) {
        auto it = lastFetchAtByDomain_.find(domain);   // when this domain was last fetched, if ever
        if (it == lastFetchAtByDomain_.end()) return true;   // never fetched before, always allowed
        return (currentTimeMillis - it->second) >= minDelayMillis_;   // enough time must have passed
    }

    // Records that a fetch to this domain just happened, at the given time.
    void recordFetch(const std::string& domain, long currentTimeMillis) {
        lastFetchAtByDomain_[domain] = currentTimeMillis;   // remember this fetch's timestamp
    }

private:
    std::map<std::string, long> lastFetchAtByDomain_;   // domain -> last fetch timestamp
    long minDelayMillis_;                                    // minimum gap required between fetches
};

int main() {
    std::cout << std::boolalpha;
    BloomFilter seenUrls(10000, 5);   // small demo filter, still plenty of bits for a handful of URLs

    seenUrls.add("https://example.com/page1");
    seenUrls.add("https://example.com/page2");
    seenUrls.add("https://test.com/home");

    std::cout << "Seen page1 correctly detected: " << seenUrls.mightContain("https://example.com/page1") << "\n";
    std::cout << "Seen page2 correctly detected: " << seenUrls.mightContain("https://example.com/page2") << "\n";
    std::cout << "Seen test.com home correctly detected: " << seenUrls.mightContain("https://test.com/home") << "\n";
    std::cout << "Never-added URL correctly reported as new: " << !seenUrls.mightContain("https://never-added.com/page") << "\n";

    PolitenessManager politeness(1000);   // require at least 1000 ms between fetches to the same domain

    std::cout << "First fetch to example.com at time 0 allowed: " << politeness.canFetchNow("example.com", 0) << "\n";
    politeness.recordFetch("example.com", 0);

    std::cout << "Second fetch to example.com at time 500 (too soon) allowed: " << politeness.canFetchNow("example.com", 500) << "\n";
    std::cout << "Meanwhile, a different domain, test.com, at time 500 allowed: " << politeness.canFetchNow("test.com", 500) << "\n";

    std::cout << "Fetch to example.com at time 1200 (enough time passed) allowed: " << politeness.canFetchNow("example.com", 1200) << "\n";
    return 0;
