from typing import Dict, List, Optional


def _string_hash(s: str) -> int:
    # A 32-bit polynomial string hash (same recurrence used by Java's own
    # String.hashCode): deterministic across languages given the same input.
    h = 0
    for ch in s:
        h = (31 * h + ord(ch)) & 0xFFFFFFFF
    if h >= (1 << 31):
        h -= (1 << 32)
    return h


class _SeededRandom:
    # A small, fixed linear-congruential generator purely so the demo's hash
    # seeds are reproducible byte-for-byte from one run to the next.
    def __init__(self, seed: int):
        self._state = (seed ^ 0x5DEECE66D) & ((1 << 48) - 1)

    def next_int(self) -> int:
        self._state = (self._state * 0x5DEECE66D + 0xB) & ((1 << 48) - 1)
        value = self._state >> 16
        if value >= (1 << 31):
            value -= (1 << 32)
        return value


# A fixed-size, space-efficient structure for probabilistic set membership.
# Guarantees no false negatives; may rarely report a false positive.
class BloomFilter:
    def __init__(self, size_in_bits: int, num_hashes: int):
        self._size = size_in_bits                     # total number of bits
        self._bits = bytearray((size_in_bits + 7) // 8)   # the shared bit array
        rng = _SeededRandom(42)                              # fixed seed, so results are reproducible every run
        self._seeds = [rng.next_int() for _ in range(num_hashes)]   # one hash seed per hash function

    # Marks a URL as seen by setting one bit per hash function.
    def add(self, url: str) -> None:
        for seed in self._seeds:
            self._set_bit(self._index_for(url, seed))   # set this hash function's bit

    # Returns false only if the URL is definitely new; true means probably
    # already seen, with a small, bounded chance of being a false positive.
    def might_contain(self, url: str) -> bool:
        for seed in self._seeds:
            if not self._get_bit(self._index_for(url, seed)):
                return False   # this bit was never set, so this URL is definitely new
        return True   # every bit was already set, probably already seen

    def _index_for(self, url: str, seed: int) -> int:
        hash_code = _string_hash(url) ^ seed   # combine the URL's hash with this function's own seed
        return hash_code % self._size             # map into a valid bit index

    def _set_bit(self, index: int) -> None:
        self._bits[index // 8] |= (1 << (index % 8))

    def _get_bit(self, index: int) -> bool:
        return (self._bits[index // 8] & (1 << (index % 8))) != 0


# Enforces a minimum delay between fetches to the same domain, tracked
# independently per domain.
class PolitenessManager:
    def __init__(self, min_delay_millis: int):
        self._last_fetch_at_by_domain: Dict[str, int] = {}   # domain -> last fetch timestamp
        self._min_delay_millis = min_delay_millis                # minimum gap required between fetches

    # Returns true if enough time has passed since this domain was last fetched.
    def can_fetch_now(self, domain: str, current_time_millis: int) -> bool:
        last_fetch_at = self._last_fetch_at_by_domain.get(domain)   # when this domain was last fetched, if ever
        if last_fetch_at is None:
            return True   # never fetched before, always allowed
        return (current_time_millis - last_fetch_at) >= self._min_delay_millis   # enough time must have passed

    # Records that a fetch to this domain just happened, at the given time.
    def record_fetch(self, domain: str, current_time_millis: int) -> None:
        self._last_fetch_at_by_domain[domain] = current_time_millis   # remember this fetch's timestamp


